function effectValue(entry,raw){const n=raw===undefined?entry.value:Number(raw);return Number.isFinite(n)&&(!entry.values||entry.values.includes(n))&&(entry.min===undefined||Number.isInteger(n)&&n>=entry.min&&n<=entry.max)?n:null;}
function selectedSpecials(s){return (Array.isArray(s.statusEffects?.specials)?s.statusEffects.specials:[]).slice(0,2).map(id=>window.SPECIAL_EFFECTS.find(e=>e.id===id)).filter(Boolean);}
function compatibleSpecials(list){return list.length<=2&&new Set(list.map(e=>e.id)).size===list.length&&list.filter(e=>e.group==='exclusive').length<=1;}
function applySetEffects(c,s,totals,unknown,records){
 const chosen=selectedSpecials(s),valid=compatibleSpecials(chosen);if((s.statusEffects?.specials||[]).filter(Boolean).length!==chosen.length)unknown.push('Item especial desconhecido ou excesso de itens; revê a seleção.');if(!valid)unknown.push('Itens especiais incompatíveis: revê a seleção.');
 const apply=(stats,source)=>{for(const [key,value] of Object.entries(stats)){if(!(key in totals))continue;totals[key]+=value;if(key==='attack')totals.attackMax+=value;records.push({source,label:window.EFFECT_LABELS[key]||key,value:'+'+value+(effectPercent(key)?'%':''),key});}};
 if(valid)for(const entry of chosen){apply(entry.stats,entry.name);if(entry.note)unknown.push(entry.name+' · '+entry.note);}
 for(const entry of window.CONSUMABLE_EFFECTS){const state=s.statusEffects?.consumables?.[entry.id];if(!state?.active)continue;if(+c.level<entry.level){unknown.push(entry.name+' · requer nível '+entry.level);continue;}const value=effectValue(entry,state.value);if(value===null){unknown.push(entry.name+' · valor inválido; efeito ignorado.');continue;}apply({[entry.key]:value},entry.name);}
}
function effectPercent(key){return !['hp','attack','defense','str','vit','int','dex'].includes(key);}
function effectSummary(stats){return Object.entries(stats).map(([k,v])=>'+'+v+(effectPercent(k)?'%':'')+' '+(window.EFFECT_LABELS[k]||elements.find(e=>e[0]===k)?.[1]||k)).join(' · ');}
function renderSetEffects(){
 const host=$('#setEffects');if(!host)return;const c=char(),s=set(),ids=(s.statusEffects?.specials||[]).slice(0,2),noSet=!c.sets.length;
 host.innerHTML=`<p class="hint">${readonly?'Simulação nesta vista; repõe ao atualizar a página.':'Escolhas guardadas por set e incluídas na partilha.'} Os efeitos só contam enquanto assinalados; não acompanha a duração real dos buffs.</p><div class="special-grid">${[0,1].map(i=>`<label>Item especial ${i+1}<select data-special-index="${i}" ${noSet?'disabled':''}><option value="">Nenhum</option>${window.SPECIAL_EFFECTS.map(e=>{const other=window.SPECIAL_EFFECTS.find(x=>x.id===ids[1-i]);const incompatible=other&&(e.id===other.id||e.group==='exclusive'&&other.group==='exclusive');return `<option value="${e.id}" ${ids[i]===e.id?'selected':''} ${incompatible?'disabled':''}>${esc(e.name)}</option>`;}).join('')}</select>${ids[i]?(()=>{const e=window.SPECIAL_EFFECTS.find(e=>e.id===ids[i]);return `${e.image?`<img class="effect-icon special-icon" src="${e.image}" alt="">`:""}<small>${esc(effectSummary(e.stats))}</small><a href="${esc(e.source)}" target="_blank" rel="noopener">Fonte ↗</a>`;})():''}</label>`).join('')}</div><details class="effects-consumables"><summary>Consumíveis e Deus Dragão</summary>${[...new Set(window.CONSUMABLE_EFFECTS.map(e=>e.group))].map(group=>`<div class="effect-group"><h3>${group}</h3><div class="consumable-grid">${window.CONSUMABLE_EFFECTS.filter(e=>e.group===group).map(e=>{const state=s.statusEffects?.consumables?.[e.id]||{},value=effectValue(e,state.value)??e.value,locked=noSet||+c.level<e.level;return `<div class="consumable-card ${state.active?'is-active':''}"><label><input type="checkbox" data-consumable="${e.id}" ${state.active?'checked':''} ${locked?'disabled':''}>${e.image?`<img class="effect-icon" src="${e.image}" alt="">`:""}<span>${esc(e.name)}<small>${esc(effectSummary({[e.key]:value}))}${locked?' · Nv. '+e.level:''}</small></span></label>${e.values?`<select aria-label="Valor de ${esc(e.name)}" data-consumable-value="${e.id}" ${locked?'disabled':''}>${e.values.map(n=>`<option value="${n}" ${n===value?'selected':''}>+${n}</option>`).join('')}</select>`:e.min!==undefined?`<label class="effect-value">Valor do frasco<input aria-label="Valor de ${esc(e.name)}" type="number" min="${e.min}" max="${e.max}" step="1" value="${value}" data-consumable-value="${e.id}" ${locked?'disabled':''}></label>`:''}<a href="${esc(e.source)}" target="_blank" rel="noopener">Fonte ↗</a>${e.note?`<small class="effect-note">${esc(e.note)}</small>`:''}</div>`;}).join('')}</div></div>`).join('')}</details><div class="combat-bonus-strip">${(()=>{const t=calculateStatus().totals;return [['monster','Monstros'],['metin','Metins'],['average','Dano médio'],['meleeMagic','Corpo a corpo/mágico'],['damageAttackPct','Ataque % (dano)']].map(([k,label])=>`<span>${label} <strong>${t[k]}%</strong></span>`).join('');})()}</div><p class="hint">Máximo de dois itens especiais; só um da categoria incompatível (Nazar, doces, medalhas, anéis ou ossos). Ataque percentual de combate não é somado como ataque fixo do painel. Água, orvalho e poção são efeitos separados.</p>`;
}
document.addEventListener('change',e=>{
 const special=e.target.dataset?.specialIndex,id=e.target.dataset?.consumable,valueId=e.target.dataset?.consumableValue;if(special===undefined&&!id&&!valueId||!char().sets.length)return;
 const s=set();s.statusEffects??={};
 if(special!==undefined){const ids=[...(s.statusEffects.specials||[])];ids[+special]=e.target.value;const entries=ids.filter(Boolean).map(id=>window.SPECIAL_EFFECTS.find(x=>x.id===id));if(entries.some(x=>!x)||!compatibleSpecials(entries)){toast('Estes itens especiais não podem ser usados juntos.');renderSetEffects();return;}s.statusEffects.specials=ids;}
 else{const entry=window.CONSUMABLE_EFFECTS.find(x=>x.id===(id||valueId));if(!entry)return;const previous=s.statusEffects.consumables?.[entry.id]||{},value=valueId?effectValue(entry,e.target.value):effectValue(entry,previous.value)??entry.value;if(value===null){toast('Escolhe um valor válido entre '+entry.min+' e '+entry.max+'.');renderSetEffects();return;}s.statusEffects.consumables={...s.statusEffects.consumables,[entry.id]:{active:id?e.target.checked:!!previous.active,value}};}
 s.statusMode='auto';save();
});
